The magic value is 19778 as a `c_ushort`, written with `fwrite`. The header is then written with `size_of::<_bmp_header>()`. That struct is 4+4+4+4+4+4+2+2+4+4+4+4+4+4 = 52 bytes, and `repr(C)` gives it the same layout as in C.

----FUNCTION----
```rust
pub unsafe extern "C" fn bmp_header_write(
    header: *const _bmp_header,
    img_file: *mut libc::FILE,
) -> bmp_error {
    if header.is_null() {
        return bmp_error::BMP_HEADER_NOT_INITIALIZED;
    } else if img_file.is_null() {
        return bmp_error::BMP_FILE_NOT_OPENED;
    }

    let magic: libc::c_ushort = 19778;
    libc::fwrite(
        &magic as *const libc::c_ushort as *const libc::c_void,
        std::mem::size_of::<libc::c_ushort>(),
        1,
        img_file,
    );

    libc::fwrite(
        header as *const libc::c_void,
        std::mem::size_of::<_bmp_header>(),
        1,
        img_file,
    );
    bmp_error::BMP_OK
}
