pub fn main() -> () {
    use std::ffi::{CStr, CString};

    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <directory>", args.get(0).map(|s| s.as_str()).unwrap_or(""));
        std::process::exit(1);
    }

    let directory = args[1].clone();
    let c_dir = match CString::new(directory.clone()) {
        Ok(c) => c,
        Err(_) => {
            println!("Error: Cannot open directory {}", directory);
            std::process::exit(1);
        }
    };

    unsafe {
        let dir = libc::opendir(c_dir.as_ptr());
        if dir.is_null() {
            println!("Error: Cannot open directory {}", directory);
            std::process::exit(1);
        }

        let mut global_checksum: u64 = 0;
